SELECT DISTINCT
  /* Full name of the member */
  CONCAT(m."first_name", ' ', m."last_name") AS "full_name",
  /* Cost of the matching expense */
  e."cost"
FROM "expense" AS e
JOIN "member" AS m
  ON e."link_to_member" = m."member_id"
WHERE e."expense_description" LIKE '%Water, Veggie tray, supplies%";

