SELECT
    /* Ratio of customers paying in EUR against customers paying in CZK */
    COUNT(DISTINCT CASE WHEN "c"."currency" = 'EUR' THEN "c"."customerid" END)::NUMERIC
    / NULLIF(COUNT(DISTINCT CASE WHEN "c"."currency" = 'CZK' THEN "c"."customerid" END), 0) AS "ratio"
FROM "customers" AS "c";

