/* Средняя цена транзакций для клиентов с валютой EUR */
SELECT AVG(t."price") AS "average_total_price"
FROM "transactions_1k" AS t
JOIN "customers" AS c
  ON t."customerid" = c."customerid"
WHERE c."currency" = 'EUR';

